    Assert-LastExitCode "Migration BL066"

    $database = "musica_aprender"
    $databaseUser = "musica_local"
    if (Test-Path ".env") {
        foreach ($line in Get-Content ".env") {
            if ($line -match '^POSTGRES_DB=(.+)$') { $database = $Matches[1].Trim() }
            if ($line -match '^POSTGRES_USER=(.+)$') { $databaseUser = $Matches[1].Trim() }
        }
    }

    $previousEnv = @{
        PGHOST = $env:PGHOST
        PGPORT = $env:PGPORT
        PGUSER = $env:PGUSER
        PGPASSWORD = $env:PGPASSWORD
        PGDATABASE = $env:PGDATABASE
        BL066_USE_DOCKER_PSQL = $env:BL066_USE_DOCKER_PSQL
    }
    try {
        $env:PGHOST = "127.0.0.1"
        $env:PGPORT = "5432"
        $env:PGUSER = $databaseUser
        $env:PGPASSWORD = "unused-docker-exec"
        $env:PGDATABASE = $database
        $env:BL066_USE_DOCKER_PSQL = "true"
        & $bash "scripts/ci/content/verify-contextual-linguistic-catalogs.sh"
        Assert-LastExitCode "Smoke BL066"
    }
    finally {
        foreach ($name in $previousEnv.Keys) {
            $value = $previousEnv[$name]
            if ($null -eq $value) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue }
            else { Set-Item "Env:$name" $value }
        }
    }
